CREATE TABLE receptions (
  id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), company_id INTEGER NOT NULL, point_id INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'in_lucru', rec_date TEXT NOT NULL, gross REAL, tare REAL, weighed INTEGER DEFAULT 1,
  vehicle_id INTEGER, vehicle_plate TEXT, driver_id INTEGER, driver_name TEXT, org_id INTEGER, metallic INTEGER DEFAULT 1, notes TEXT,
  created TEXT, created_by TEXT, finalized_at TEXT, finalized_by TEXT, siatd_sent INTEGER DEFAULT 0, siatd_at TEXT, siatd_by TEXT
);
CREATE TABLE hus (
  id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL, tare REAL DEFAULT 0, point_id INTEGER NOT NULL,
  label_hash TEXT, label_printed TEXT, created TEXT
);
CREATE TABLE reception_items (
  id INTEGER PRIMARY KEY, reception_id INTEGER NOT NULL REFERENCES receptions(id), order_line_id INTEGER, article_id INTEGER NOT NULL,
  ewc_id INTEGER, hu_id INTEGER, lot TEXT NOT NULL, kg REAL NOT NULL, pcs INTEGER, price REAL, org_id INTEGER, is_new INTEGER DEFAULT 0,
  created TEXT, created_by TEXT
);
CREATE TABLE reception_deductions (id INTEGER PRIMARY KEY, reception_id INTEGER NOT NULL, kind TEXT NOT NULL, kg REAL NOT NULL);
CREATE TABLE reception_docs (
  id INTEGER PRIMARY KEY, reception_id INTEGER NOT NULL, kind TEXT NOT NULL, number TEXT NOT NULL, ewc_id INTEGER, org_id INTEGER,
  hash TEXT, version INTEGER DEFAULT 1, issued_at TEXT, printed_at TEXT, data TEXT
);
CREATE TABLE stock (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, point_id INTEGER NOT NULL, hu_id INTEGER, article_id INTEGER NOT NULL, ewc_id INTEGER,
  lot TEXT, org_id INTEGER, kg REAL NOT NULL, pcs INTEGER, status TEXT NOT NULL DEFAULT 'disponibil', regime TEXT DEFAULT 'propriu',
  partner_id INTEGER, order_id INTEGER, reception_id INTEGER, item_id INTEGER, price REAL, created TEXT
);
